The good news is we haven't done the same thing in another place. I have checked the codebase at `master` using this naive analyzer.

```go
func run(pass *analysis.Pass) (interface{}, error) {
	inspect := pass.ResultOf[inspect.Analyzer].(*inspector.Inspector)
	nodeFilter := []ast.Node{
		(*ast.BinaryExpr)(nil),
	}

	const typeName = "github.com/pingcap/tidb/kv.Handle"

	inspect.Preorder(nodeFilter, func(node ast.Node) {
		expr := node.(*ast.BinaryExpr)

		if expr.Op != token.EQL && expr.Op != token.NEQ {
			return
		}

		if pass.TypesInfo.TypeOf(expr.X).String() != typeName || pass.TypesInfo.TypeOf(expr.Y).String() != typeName {
			return
		}

		pass.Reportf(expr.Pos(), "use %s on two handle type", expr.Op.String())
	})

	return nil, nil
}
```

